package com.pensefit.app;
import android.app.*;
import android.content.*;
import android.content.pm.ServiceInfo;
import android.location.*;
import android.os.*;
import android.speech.tts.TextToSpeech;
import androidx.core.app.NotificationCompat;
import org.json.*;
import java.util.*;

public class ActiveService extends Service implements LocationListener,TextToSpeech.OnInitListener {
 static ActiveService instance;
 private final Handler handler=new Handler(Looper.getMainLooper());
 private final Map<String,JSONObject> timers=new HashMap<>();
 private PowerManager.WakeLock wake;private JSONObject voiceOptions;
 private final Set<String> delivered=new HashSet<>();
 private ActiveVault vault;private LocationManager manager;private TextToSpeech tts;private boolean voiceReady=false,running=false;
 private String account="";private JSONObject data;private Location last;private long activeAt=0;private double baseSeconds=0;
 private final Runnable tick=new Runnable(){public void run(){try{tickTimers();if(running){snapshot();showNotification();}}catch(Exception ignored){}handler.postDelayed(this,1000);}};
 @Override public void onCreate(){super.onCreate();instance=this;vault=new ActiveVault(this);manager=(LocationManager)getSystemService(LOCATION_SERVICE);tts=new TextToSpeech(this,this);NotificationManager nm=getSystemService(NotificationManager.class);nm.createNotificationChannel(new NotificationChannel("pense-active","Atividades PenseFit",NotificationManager.IMPORTANCE_LOW));PowerManager power=(PowerManager)getSystemService(POWER_SERVICE);wake=power.newWakeLock(PowerManager.PARTIAL_WAKE_LOCK,"PenseFit:ActiveSession");handler.post(tick);}
 @Override public int onStartCommand(Intent intent,int flags,int startId){if(intent==null)return START_NOT_STICKY;String action=intent.getAction();try{
  String next=intent.getStringExtra("account");if(next!=null&&!next.isEmpty()){if(!account.isEmpty()&&!account.equals(next))stopTracking();account=next;}
  if("run-start".equals(action)){JSONObject options=new JSONObject(intent.getStringExtra("options"));voiceOptions=options.optJSONObject("voice");data=options.getJSONObject("data");baseSeconds=data.optDouble("movingSeconds",0);activeAt=System.currentTimeMillis();data.put("status","active");running=true;last=null;if(!wake.isHeld())wake.acquire();showNotification();long frequency="balanced".equals(options.optString("accuracy"))?5000:2000;manager.requestLocationUpdates(LocationManager.GPS_PROVIDER,frequency,3,this);manager.requestLocationUpdates(LocationManager.NETWORK_PROVIDER,frequency,3,this);snapshot();}
  else if("run-pause".equals(action)){snapshot();stopTracking();if(data!=null){data.put("status","paused");vault.write(account,"run",data.toString());}showNotification();PenseActivePlugin.emit("command",new JSONObject().put("action","pause"));}
  else if("run-resume".equals(action)){if(data!=null){baseSeconds=data.optDouble("movingSeconds",0);activeAt=System.currentTimeMillis();data.put("status","active");running=true;last=null;manager.requestLocationUpdates(LocationManager.GPS_PROVIDER,2000,3,this);showNotification();PenseActivePlugin.emit("command",new JSONObject().put("action","resume"));}}
  else if("run-stop".equals(action)){snapshot();stopTracking();if(data!=null){data.put("status","paused");vault.write(account,"run",data.toString());}data=null;if(timers.isEmpty())stopSelf();else showNotification();}
  else if("timer".equals(action)){JSONObject options=new JSONObject(intent.getStringExtra("options"));timers.put(options.getString("kind"),options);if(!wake.isHeld())wake.acquire();vault.write(account,"timers",new JSONObject(timers).toString());showNotification();}
  else if("timer-stop".equals(action)){timers.remove(intent.getStringExtra("kind"));vault.write(account,"timers",new JSONObject(timers).toString());if(timers.isEmpty()&&!running)stopSelf();}
  else if("speak".equals(action)){showNotification();JSONObject o=new JSONObject(intent.getStringExtra("options"));handler.postDelayed(()->say(o.optString("text"),(float)o.optDouble("volume",.8),(float)o.optDouble("rate",1)),700);handler.postDelayed(()->{if(!running&&timers.isEmpty())stopSelf();},15000);}
 }catch(Exception e){try{PenseActivePlugin.emit("location",new JSONObject().put("error","Localização ou serviço indisponível. Retome pelo aplicativo."));}catch(Exception ignored){}stopTracking();stopSelf();}return START_NOT_STICKY;}
 private void stopTracking(){running=false;last=null;try{manager.removeUpdates(this);}catch(Exception ignored){}}
 private void snapshot()throws Exception{if(data==null||account.isEmpty())return;long now=System.currentTimeMillis();if(running)data.put("movingSeconds",baseSeconds+(now-activeAt)/1000.0);data.put("elapsedSeconds",Math.max(data.optDouble("elapsedSeconds"),(now-data.optDouble("startedTimestamp",now))/1000.0));vault.write(account,"run",data.toString());}
 @Override public void onLocationChanged(Location location){if(!running||data==null)return;try{long now=System.currentTimeMillis();if(!location.hasAccuracy()||location.getAccuracy()>35||Math.abs(now-location.getTime())>30000||Math.abs(location.getLatitude())>90||Math.abs(location.getLongitude())>180){PenseActivePlugin.emit("location",new JSONObject().put("error","Leitura GPS imprecisa ignorada."));return;}snapshot();double distance=0;boolean segment=last==null;JSONArray points=data.optJSONArray("points");if(points==null)points=new JSONArray();if(points.length()>=20000){stopTracking();PenseActivePlugin.emit("command",new JSONObject().put("action","pause").put("reason","Limite de pontos atingido."));return;}if(last!=null){double dt=(location.getTime()-last.getTime())/1000.0;if(dt<=0)return;distance=last.distanceTo(location);if(dt>30){distance=0;segment=true;data.put("gaps",data.optInt("gaps")+1);}else if(distance/dt>10)return;else if(distance<Math.max(3,Math.min(location.getAccuracy(),last.getAccuracy())*.4))return;}
  double before=data.optDouble("distanceMeters"),after=before+distance,seconds=data.optDouble("movingSeconds");JSONArray splits=data.optJSONArray("splits");if(splits==null)splits=new JSONArray();for(double target=(Math.floor(before/1000)+1)*1000;target<=after;target+=1000){JSONObject previous=points.optJSONObject(points.length()-1);double time=distance>0&&previous!=null?previous.optDouble("seconds")+(seconds-previous.optDouble("seconds"))*(target-before)/distance:seconds,prior=splits.length()>0?splits.getJSONObject(splits.length()-1).optDouble("cumulativeSeconds"):0;splits.put(new JSONObject().put("km",target/1000).put("seconds",time-prior).put("cumulativeSeconds",time));if(voiceOptions!=null&&voiceOptions.optBoolean("enabled"))say("Você completou o quilômetro "+(int)(target/1000)+".",(float)voiceOptions.optDouble("volume",.8),(float)voiceOptions.optDouble("rate",1));}
  JSONObject point=new JSONObject().put("lat",location.getLatitude()).put("lon",location.getLongitude()).put("timestamp",location.getTime()).put("accuracy",location.getAccuracy()).put("seconds",seconds).put("distance",after).put("segment",segment);points.put(point);data.put("points",points).put("splits",splits).put("distanceMeters",after);last=location;snapshot();PenseActivePlugin.emit("location",new JSONObject().put("data",data));
 }catch(Exception e){stopTracking();}}
 private void tickTimers()throws Exception{long now=System.currentTimeMillis();for(JSONObject timer:timers.values()){JSONArray events=timer.optJSONArray("events");if(events==null)continue;JSONObject voice=timer.optJSONObject("voice");for(int i=0;i<events.length();i++){JSONObject e=events.getJSONObject(i);String key=timer.optString("id")+":"+e.optLong("at")+":"+e.optString("text");if(now>=e.optLong("at")&&now-e.optLong("at")<10000&&delivered.add(key)){if(voice!=null&&voice.optBoolean("enabled"))say(e.optString("text"),(float)voice.optDouble("volume",.8),(float)voice.optDouble("rate",1));Vibrator v=(Vibrator)getSystemService(VIBRATOR_SERVICE);if(v!=null)v.vibrate(VibrationEffect.createOneShot(150,VibrationEffect.DEFAULT_AMPLITUDE));}}}}
 void say(String text,float volume,float rate){if(!voiceReady||text.isEmpty())return;tts.setSpeechRate(rate);Bundle b=new Bundle();b.putFloat(TextToSpeech.Engine.KEY_PARAM_VOLUME,Math.max(0,Math.min(1,volume)));tts.speak(text,TextToSpeech.QUEUE_ADD,b,UUID.randomUUID().toString());}
 @Override public void onInit(int status){voiceReady=status==TextToSpeech.SUCCESS;if(voiceReady)tts.setLanguage(new Locale("pt","BR"));}
 private PendingIntent command(String action,int code){return PendingIntent.getService(this,code,new Intent(this,ActiveService.class).setAction(action),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 private void showNotification(){String title=data!=null?data.optString("name","Pense Run"):"Pense Active",text=data!=null?String.format(Locale.US,"%.2f km · %d min",data.optDouble("distanceMeters")/1000,data.optDouble("movingSeconds")/60):"Treino em andamento · alertas de intervalo";Intent launch=new Intent(this,MainActivity.class);PendingIntent open=PendingIntent.getActivity(this,0,launch,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);NotificationCompat.Builder b=new NotificationCompat.Builder(this,"pense-active").setSmallIcon(android.R.drawable.ic_media_play).setContentTitle(title).setContentText(text).setContentIntent(open).setOngoing(true).setOnlyAlertOnce(true).setVisibility(NotificationCompat.VISIBILITY_PRIVATE);if(data!=null)b.addAction(0,running?"Pausar":"Continuar",command(running?"run-pause":"run-resume",1));int type=data!=null?ServiceInfo.FOREGROUND_SERVICE_TYPE_LOCATION:(Build.VERSION.SDK_INT>=34?ServiceInfo.FOREGROUND_SERVICE_TYPE_SPECIAL_USE:0);if(Build.VERSION.SDK_INT>=29)startForeground(42,b.build(),type);else startForeground(42,b.build());}
 JSONObject stopFromBridge()throws Exception{snapshot();stopTracking();JSONObject result=data;if(result!=null){result.put("status","paused");vault.write(account,"run",result.toString());}data=null;if(timers.isEmpty())stopSelf();return result;}
 @Override public IBinder onBind(Intent i){return null;}
 @Override public void onDestroy(){try{snapshot();if(data!=null){data.put("status","paused");vault.write(account,"run",data.toString());}}catch(Exception ignored){}stopTracking();handler.removeCallbacksAndMessages(null);if(tts!=null){tts.stop();tts.shutdown();}if(wake!=null&&wake.isHeld())wake.release();instance=null;super.onDestroy();}
}
